import React from 'react';

const DetailsStep = ({ character, handleWeaponChange, handleRemoveWeapon, handleAddWeapon, calculateModifier, profBonus }) => {

    // Akıllı Zar Ayrıştırıcı (Geliştirilmiş)
    const parseDice = (diceString) => {
        if (!diceString) return { dice: [], flatBonus: 0 };
        const cleanStr = diceString.replace(/\s+/g, '').toLowerCase();
        const diceRegex = /(\d+)d(\d+)/g;
        const flatRegex = /([+-]\d+)(?!d)/g;
        let dice = []; let match;
        while ((match = diceRegex.exec(cleanStr)) !== null) {
            dice.push({ count: parseInt(match[1]), sides: parseInt(match[2]) });
        }
        let flatBonus = 0;
        while ((match = flatRegex.exec(cleanStr)) !== null) {
            flatBonus += parseInt(match[1]);
        }
        return { dice, flatBonus };
    };

    return (
        <div className="step-content fade-in">
            <div className="weapons-section">
                <div className="section-header">
                    <h2>Attacks & Weapons</h2>
                    <button type="button" className="add-weapon-btn" onClick={handleAddWeapon}>+ ADD WEAPON</button>
                </div>

                <div className="weapons-list">
                    {character.weapons.map((weapon) => {
                        const statMod = calculateModifier(character.stats[weapon.stat]);

                        // ATAK HESABI: 1d20 + Stat + Prof + (Varsa silahtaki +1, +2 bonusu)
                        const { flatBonus: weaponAtkBonus } = parseDice(weapon.attackBonusDice || ""); 
                        const totalAtkBonus = statMod + (weapon.isProficient ? profBonus : 0) + weaponAtkBonus;

                        // HASAR HESABI: Zar Dizisi + Stat + Silahtaki Sabit Bonus
                        const { dice, flatBonus: weaponDmgBonus } = parseDice(weapon.damageDice);
                        const totalDmgBonus = statMod + weaponDmgBonus;
                        const diceDisplay = dice.map(d => `${d.count}d${d.sides}`).join(' + ');

                        return (
                            <div className={`weapon-card ${weapon.type === 'Ranged' ? 'ranged-style' : ''}`} key={weapon.id}>
                                <div className="weapon-main-row">
                                    <div className="weapon-type-badge">{weapon.type || 'Melee'}</div>
                                    <input type="text" className="weapon-name" value={weapon.name} onChange={(e) => handleWeaponChange(weapon.id, 'name', e.target.value)} placeholder="Weapon Name" />
                                    <button type="button" className="remove-weapon-btn" onClick={() => handleRemoveWeapon(weapon.id)}>✕</button>
                                </div>

                                <div className="weapon-details-grid">
                                    {/* SİLAH TİPİ SEÇİMİ */}
                                    <div className="weapon-detail-box">
                                        <label>Type</label>
                                        <select value={weapon.type} onChange={(e) => handleWeaponChange(weapon.id, 'type', e.target.value)}>
                                            <option value="Melee">⚔️ Melee</option>
                                            <option value="Ranged">🏹 Ranged</option>
                                        </select>
                                    </div>

                                    {/* HANGİ STAT? */}
                                    <div className="weapon-detail-box">
                                        <label>Ability</label>
                                        <select value={weapon.stat} onChange={(e) => handleWeaponChange(weapon.id, 'stat', e.target.value)}>
                                            <option value="Strength">STR</option>
                                            <option value="Dexterity">DEX</option>
                                        </select>
                                    </div>

                                    {/* ATAK BONUSU (ZARLI: Örn +1, -1 veya 1d4) */}
                                    <div className="weapon-detail-box">
                                        <label>Atk Magic</label>
                                        <input type="text" placeholder="+1" value={weapon.attackBonusDice} onChange={(e) => handleWeaponChange(weapon.id, 'attackBonusDice', e.target.value)} />
                                    </div>

                                    {/* HASAR ZARI */}
                                    <div className="weapon-detail-box">
                                        <label>Damage Dice</label>
                                        <input type="text" placeholder="1d8" value={weapon.damageDice} onChange={(e) => handleWeaponChange(weapon.id, 'damageDice', e.target.value)} />
                                    </div>

                                    {/* MENZİL (SADECE RANGED İSE GÖRÜNÜR) */}
                                    {weapon.type === 'Ranged' && (
                                        <div className="weapon-detail-box range-box">
                                            <label>Range (ft)</label>
                                            <input type="text" placeholder="80/320" value={weapon.range} onChange={(e) => handleWeaponChange(weapon.id, 'range', e.target.value)} />
                                        </div>
                                    )}

                                    <div className="weapon-detail-box prof-box">
                                        <label>Prof.</label>
                                        <div className={`custom-prof-toggle ${weapon.isProficient ? 'active' : ''}`} onClick={() => handleWeaponChange(weapon.id, 'isProficient', !weapon.isProficient)}></div>
                                    </div>
                                </div>

                                {/* HESAPLANMIŞ SONUÇ BARI */}
                                <div className="weapon-calc-bar">
                                    <div className="calc-item">
                                        <span className="calc-label">TOTAL HIT:</span>
                                        <span className="calc-val atk-val">1d20 {totalAtkBonus >= 0 ? `+ ${totalAtkBonus}` : `- ${Math.abs(totalAtkBonus)}`}</span>
                                    </div>
                                    <div className="calc-item">
                                        <span className="calc-label">TOTAL DAMAGE:</span>
                                        <span className="calc-val dmg-val">
                                            {diceDisplay ? `${diceDisplay} ${totalDmgBonus >= 0 ? '+' : ''} ${totalDmgBonus}` : '--'}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

export default DetailsStep;
